cd /tmp && python - <<'EOF'
import sys, six
from six import moves

# Node 1: types & constants
assert isinstance("hi", six.string_types)
assert isinstance(1, six.integer_types)
assert isinstance(six.text_type("hi"), six.string_types)
assert type(six.b("hi")) is six.binary_type
assert six.MAXSIZE > 1000

# Node 2: six.moves
from six.moves import queue, configparser
assert isinstance(queue.Queue(), object)
assert isinstance(configparser.ConfigParser(), object)

# Node 3: iterators & dict
d = {'a': 1, 'b': 2}
assert set(six.iterkeys(d)) == {'a', 'b'}
assert set(six.itervalues(d)) == {1, 2}
assert set(six.iteritems(d)) == {('a', 1), ('b', 2)}
assert set(six.viewkeys(d)) == {'a', 'b'}
assert set(six.viewvalues(d)) == {1, 2}
assert set(six.viewitems(d)) == {('a', 1), ('b', 2)}

# Node 4: bytes/strings
assert isinstance(six.b("hello"), six.binary_type)
assert isinstance(six.u("hello"), six.text_type)
assert six.byte2int(six.b("\x03")) == 3
assert six.ensure_binary("hi") == b"hi"
assert six.ensure_str(b"hi") == "hi"
assert six.ensure_text(b"hi") == "hi"
assert six.unichr(65) == "A" and six.int2byte(65) == b"A"

# Node 5: function attrs
def f(x, y=3): pass
assert isinstance(six.get_function_code(f), type(f.__code__))
assert six.get_function_defaults(f) == (3,)
assert six.get_function_globals(f) is globals()
assert six.get_function_closure(f) is None

# Node 6: syntax & exceptions
ns = {}
six.exec_("x = 42", ns)
assert ns["x"] == 42
try:
    six.raise_from(ValueError("foo"), None)
except Exception as e:
    assert str(e) == "foo"
try:
    raise ValueError("x")
except ValueError:
    tp, v, tb = sys.exc_info()
    try:
        six.reraise(tp, v, tb)
    except ValueError:
        pass
import io as _io
b = _io.StringIO(); six.print_("Hello", "World", sep=", ", file=b)
assert b.getvalue() == "Hello, World\n"

# Node 7: metaclass & decorators
@six.python_2_unicode_compatible
class MyClass(six.with_metaclass(type, object)):
    def __str__(self):
        return six.u("hello")
assert str(MyClass()) == six.u("hello")

# Node 8: unittest assertions
import unittest
class Test(unittest.TestCase):
    def test(self):
        six.assertCountEqual(self, [1, 2], [2, 1])
        with self.assertRaises(AssertionError):
            six.assertRegex(self, 'test', r'^a')
        six.assertRegex(self, 'test', r'^t')
Test('test').test()

# Node 9: wraps
def original():
    """docstring"""
    return 42
@six.wraps(original)
def wrapper():
    return original()
assert wrapper.__name__ == "original"
assert wrapper.__doc__ == "docstring"
assert wrapper() == 42

# Node 10: StringIO / BytesIO
fp = six.StringIO(); fp.write(six.u("hello")); assert fp.getvalue() == six.u("hello")
bp = six.BytesIO(); bp.write(six.b("hello")); assert bp.getvalue() == six.b("hello")

# Nodes 11-15: range/xrange, input/raw_input, reduce, filter/map, zip
from six.moves import range, xrange, reduce, filter, map, zip, input, raw_input
assert list(range(5)) == [0, 1, 2, 3, 4]
assert list(xrange(5)) == [0, 1, 2, 3, 4]
assert reduce(lambda x, y: x + y, [1, 2, 3, 4]) == 10
assert list(filter(lambda x: x % 2 == 0, [1, 2, 3, 4])) == [2, 4]
assert list(map(lambda x: x * 2, [1, 2, 3, 4])) == [2, 4, 6, 8]
assert list(zip([1, 2, 3], ['a', 'b', 'c'])) == [(1, 'a'), (2, 'b'), (3, 'c')]
assert input is raw_input  # both map to builtins.input on PY3

# Practical examples from spec
def process_string(data):
    if isinstance(data, six.binary_type):
        data = six.ensure_text(data, encoding='utf-8')
    return six.ensure_binary(data.upper(), encoding='utf-8')
assert process_string("hello") == b'HELLO'
assert process_string(b"hello") == b'HELLO'

class NumberIterator(six.Iterator):
    def __init__(self, start, end):
        self.current = start
        self.end = end
    def __iter__(self):
        return self
    def __next__(self):
        if self.current >= self.end:
            raise StopIteration
        result = self.current
        self.current += 1
        return result
assert list(NumberIterator(1, 5)) == [1, 2, 3, 4]

def process_dict(d):
    result = {}
    for key, value in six.iteritems(d):
        result[key] = value.upper() if isinstance(value, six.string_types) else value
    return result
assert process_dict({'a': 'hello', 'b': 'world', 'c': 123}) == {'a': 'HELLO', 'b': 'WORLD', 'c': 123}

def safe_operation():
    try:
        1 / 0
    except Exception as e:
        six.raise_from(RuntimeError("Operation failed"), e)
try:
    safe_operation()
except RuntimeError as e:
    assert str(e) == "Operation failed"

# advanced: add_move/remove_move
from six import MovedModule, MovedAttribute, add_move, remove_move
add_move(MovedModule("my_os", "os", "os"))
assert moves.my_os.name == __import__("os").name
remove_move("my_os")

print("ALL 15 NODES VERIFIED OK")
EOF
